changeSet.sql:
ALTER TABLE employees ADD COLUMN department_id  UUID REFERENCES departments(id);
ALTER TABLE employees ADD COLUMN designation_id UUID REFERENCES designations(id);

CREATE INDEX idx_employees_department ON employees (tenant_id, department_id);
CREATE INDEX idx_employees_designation ON employees (tenant_id, designation_id);

rollback.sql:
DROP INDEX IF EXISTS idx_employees_designation;
DROP INDEX IF EXISTS idx_employees_department;
ALTER TABLE employees DROP COLUMN IF EXISTS designation_id;
ALTER TABLE employees DROP COLUMN IF EXISTS department_id;

changeSet.sql:
DO $$ DECLARE t RECORD; BEGIN FOR t IN SELECT DISTINCT tenant_id FROM employees LOOP PERFORM set_config('app.current_tenant_id', t.tenant_id::text, false);
-- One department row per distinct normalised spelling. DISTINCT ON keeps the -- first spelling encountered, so the tenant keeps a name they actually typed. INSERT INTO departments (tenant_id, name) SELECT DISTINCT ON (lower(trim(e.department))) t.tenant_id, trim(e.department) FROM employees e WHERE e.tenant_id = t.tenant_id AND e.department IS NOT NULL AND trim(e.department) <> '' ORDER BY lower(trim(e.department)), e.created_at, e.id ON CONFLICT DO NOTHING;
UPDATE employees e SET department_id = d.id FROM departments d WHERE e.tenant_id = t.tenant_id AND d.tenant_id = t.tenant_id AND e.department IS NOT NULL AND trim(e.department) <> '' AND lower(trim(e.department)) = lower(trim(d.name));
INSERT INTO designations (tenant_id, name) SELECT DISTINCT ON (lower(trim(e.designation))) t.tenant_id, trim(e.designation) FROM employees e WHERE e.tenant_id = t.tenant_id AND e.designation IS NOT NULL AND trim(e.designation) <> '' ORDER BY lower(trim(e.designation)), e.created_at, e.id ON CONFLICT DO NOTHING;
UPDATE employees e SET designation_id = g.id FROM designations g WHERE e.tenant_id = t.tenant_id AND g.tenant_id = t.tenant_id AND e.designation IS NOT NULL AND trim(e.designation) <> '' AND lower(trim(e.designation)) = lower(trim(g.name)); END LOOP;
-- Reset so the connection Liquibase hands back carries no tenant. PERFORM set_config('app.current_tenant_id', '', false); END $$;
